"§1 pracownik zostaje zatrudniony na stanowisku magazyniera w pełnym wymiarze czasu pracy miejscem wykonywania pracy jest magazyn pracodawcy w miejscowości zielona dolina do obowiązków pracownika należy w szczególności przyjmowanie i wydawanie towaru kompletowanie zamówień oraz dbanie o porządek na stanowisku pracy": "audio/tts/1-pracownik-zostaje-zatrudniony-na-stano-60f67b73-f.mp3",
"§2 pracownikowi przysługuje wynagrodzenie zasadnicze w wysokości określonej w załączniku nr 1 do niniejszej umowy płatne do dziesiątego dnia następnego miesiąca na rachunek bankowy wskazany przez pracownika za pracę w godzinach nadliczbowych pracownikowi przysługuje dodatek zgodnie z przepisami prawa pracy": "audio/tts/2-pracownikowi-przysuguje-wynagrodzenie--0cb31ea8-f.mp3",
"§3 czas pracy wynosi 8 godzin na dobę i przeciętnie 40 godzin w tygodniu praca wykonywana jest w systemie dwuzmianowym zgodnie z harmonogramem ustalanym przez kierownika pracownikowi przysługuje urlop wypoczynkowy w wymiarze wynikającym z przepisów": "audio/tts/3-czas-pracy-wynosi-8-godzin-na-dobe-i-p-77b3e562-f.mp3",
"§4 każda ze stron może rozwiązać umowę za wypowiedzeniem okres wypowiedzenia zależy od czasu zatrudnienia u pracodawcy wszelkie zmiany umowy wymagają formy pisemnej pod rygorem nieważności umowę sporządzono w dwóch jednobrzmiących egzemplarzach po jednym dla każdej ze stron": "audio/tts/4-kazda-ze-stron-moze-rozwiazac-umowe-za-6791acb8-f.mp3",
